package composer_native

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"unicode"
	"unicode/utf8"
)

const MaxActivationAckBytes = 8 * 1024

var ErrHotDocumentMissing = errors.New("native hot document missing")

// HotActivationRequest is an existing-binding CAS, never a seed. Next epoch is
// generated by the native owner, not supplied or reusable by an adapter.
type HotActivationRequest struct {
	Epoch              string `json:"epoch"`
	DocKey             string `json:"docKey"`
	AccountScope       string `json:"accountScope"`
	TargetDocKey       string `json:"targetDocKey"`
	TargetAccountScope string `json:"targetAccountScope"`
}
type HotActivationAck struct {
	Kind                 string `json:"kind"`
	ID                   uint64 `json:"id"`
	Epoch                string `json:"epoch"`
	DocKey               string `json:"docKey"`
	AccountScope         string `json:"accountScope"`
	Revision             uint64 `json:"revision"`
	SemanticRevision     uint64 `json:"semanticRevision"`
	SemanticDigest       string `json:"semanticDigest"`
	ActivationGeneration uint64 `json:"activationGeneration"`
	RequiresSnapshot     bool   `json:"requiresSnapshot"`
	Error                string `json:"error,omitempty"`
}

// ActivationRejected is a before-native-mutation failure. Only the missing
// document sentinel permits a future adapter to consider its cold seed path.
type ActivationRejected struct{ Code string }

func (e *ActivationRejected) Error() string { return e.Code }
func (e *ActivationRejected) Is(target error) bool {
	return target == ErrHotDocumentMissing && e.Code == "HOT_DOCUMENT_MISSING"
}
func activationIdentity(value string, maximum int, empty bool) bool {
	return (empty || value != "") && len(value) <= maximum && utf8.ValidString(value) && !strings.ContainsFunc(value, func(r rune) bool { return r < 32 || r == 127 || unicode.IsControl(r) })
}
func (r HotActivationRequest) validate() error {
	if !activationIdentity(r.Epoch, 256, true) || !activationIdentity(r.DocKey, 2048, true) || !activationIdentity(r.AccountScope, 512, true) || !activationIdentity(r.TargetDocKey, 2048, false) || !activationIdentity(r.TargetAccountScope, 512, false) {
		return errors.New("invalid hot activation identity")
	}
	return nil
}
func lowercaseHex(value string, size int) bool {
	if len(value) != size {
		return false
	}
	for _, c := range value {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}
func activationEpoch(namespace string, generation uint64) string {
	return fmt.Sprintf("native-hot:%s:%d", namespace, generation)
}
func decodeHotActivationAck(raw []byte, id uint64, request HotActivationRequest, namespace string, next, after uint64) (HotActivationAck, error) {
	var ack HotActivationAck
	if len(raw) > MaxActivationAckBytes {
		return ack, errors.New("hot activation acknowledgement too large")
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&ack); err != nil {
		return ack, err
	}
	var trailing any
	if decoder.Decode(&trailing) != io.EOF {
		return ack, errors.New("trailing activation data")
	}
	if ack.Error != "" {
		if len(ack.Error) > 128 || !activationIdentity(ack.Error, 128, false) {
			return ack, errors.New("invalid activation rejection")
		}
		var fields map[string]json.RawMessage
		_ = json.Unmarshal(raw, &fields)
		if len(fields) != 1 || !knownActivationRejection(ack.Error) {
			return ack, errors.New("unrecognized native activation rejection")
		}
		return ack, &ActivationRejected{Code: ack.Error}
	}
	if err := request.validate(); err != nil {
		return ack, err
	}
	if !lowercaseHex(namespace, 32) || next == 0 || ack.Kind != "hotActivated" || ack.ID != id || ack.DocKey != request.TargetDocKey || ack.AccountScope != request.TargetAccountScope || ack.ActivationGeneration != next || ack.Epoch != activationEpoch(namespace, next) || ack.Revision <= after || ack.SemanticRevision == 0 || !lowercaseHex(ack.SemanticDigest, 64) || !ack.RequiresSnapshot {
		return ack, errors.New("stale or malformed hot activation acknowledgement")
	}
	return ack, nil
}

func knownActivationRejection(code string) bool {
	switch code {
	case "CLOSED", "INVALID_JSON", "INVALID_OPERATION", "INVALID_ACTIVATION_IDENTITY", "STALE_ACTIVATION_SOURCE", "STALE_ACTIVATION_GENERATION", "STALE_ACTIVATION_REVISION", "ACTIVATION_GENERATION_EXHAUSTED", "HOT_DOCUMENT_MISSING", "HOT_DOCUMENT_ACCOUNT_MISMATCH", "HOT_DOCUMENT_SELECTION_INVALID", "INVALID_HOT_SEMANTIC_METADATA", "ACTIVATION_EPOCH_CONFLICT", "ACTIVATION_ACK_TOO_LARGE":
		return true
	default:
		return false
	}
}
